    if comp.get('name') == 'NavInner':
        nav_inner = (key, comp)
        break

if nav_inner:
    print("NavInner children:", nav_inner[1].get('children'))

# Let's check NavLeft children
for key, comp in cd.items():
    if comp.get('name') == 'NavLeft':
        print("NavLeft children:", comp.get('children'))
        print("NavLeft styleProps:", json.dumps(comp.get('styleProperties', {}), indent=2))

# Check LogoImg src
for key, comp in cd.items():
    if comp.get('name') == 'LogoImg':
        print("LogoImg props:", json.dumps(comp.get('properties', {}), indent=2))

